    }

    @Test
    public void textMethodReturnsCorrectString() {
        String text = BLANK_TEXT;
        TextNode textNode = new TextNode(text);
        Assert.assertEquals(StringUtil.normaliseWhitespace(text), textNode.text());
    }

    @Test
    public void setTextNodeSetsCorrectText() {
        String originalText = BLANK_TEXT;
        TextNode textNode = new TextNode(originalText);
        textNode.text(BLANK_TEXT + "New");
        Assert.assertEquals(originalText, textNode.getWholeText());
    }

    @Test
    public void splitTextReturnsCorrectTextNode() {
        String text = BLANK_TEXT;
        TextNode textNode = new TextNode(text);
        int offset = OFFSET_1;
        TextNode resultTextNode = textNode.splitText(offset);
        Assert.assertEquals(StringUtil.normaliseWhitespace(text.substring(0, offset)), resultTextNode.getWholeText());
    }

    @Test
    public void splitTextReturnsBlankTextNodeForEmptyOffset() {
        String text = BLANK_TEXT;
        TextNode textNode = new TextNode(text);
        int offset = 0;
        TextNode resultTextNode = textNode.splitText(offset);
        Assert.assertTrue(resultTextNode.isBlank());
    }

    @Test
    public void isBlankMethodReturnsCorrectBoolean() {
        String blankText = BLANK_TEXT;
        String nonBlankText = "Non Blank";
        TextNode textNode1 = new TextNode(blankText);
        TextNode textNode2 = new TextNode(nonBlankText);

        Assert.assertTrue(textNode1.isBlank());
        Assert.assertFalse(textNode2.isBlank());
    }

    @Test
    public void cloneMethodReturnsCorrectTextNode() {
        String originalText = BLANK_TEXT;
        TextNode textNode = new TextNode(originalText);
        TextNode clonedTextNode = textNode.clone();
        Assert.assertEquals(StringUtil.normaliseWhitespace(originalText), clonedTextNode.getWholeText());
    }

    @Test
    public void createFromEncodedMethodCreatesCorrectTextNode() {
        String encodedText = "&lt;BLANK&gt;";
        TextNode textNode = TextNode.createFromEncoded(encodedText);
        Assert.assertTrue(textNode.isBlank());
    }
